class AstNode:
    kind: int
    parent: weakref AstNode = None

fn parse_expr(ref mut nodes: Arena) -> int:
    root = AstNode(kind=1) using nodes
    leaf = AstNode(kind=2) using nodes
    leaf.parent = weakref root
    if leaf.parent exists as p:
        return p.kind
    return 0

fn main():
    nodes = Arena.with_capacity(4096)
    println(parse_expr(ref mut nodes))

class Sprite:
    x: int

class Hud:
    focus: weakref Sprite = None

fn draw_frame(ref mut frame: Arena, ref mut hud: Hud, i: int):
    s = Sprite(x=i) using frame
    hud.focus = weakref s
    println(s.x)

fn main():
    frame = Arena.with_capacity(64 * 1024)
    hud = Hud()
    for i in 0..3:
        draw_frame(ref mut frame, ref mut hud, i)
        frame.reset()
    if hud.focus exists as s:
        println(s.x)

class Enemy:
    hp: int

struct Target:
    enemy: weakref Enemy = None

fn pick_target() -> Target:
    wave = Arena.with_capacity(4096)
    e = Enemy(hp=30) using wave
    t = Target()
    t.enemy = weakref e
    return t

fn main():
    t = pick_target()
    if t.enemy exists as e:
        println(e.hp)
    else:
        println("gone")

