class Decl:
    name: String

fn parse_decls(src: StrView) -> Array[weakref Decl]:
    ast = Arena.with_capacity(256 * 1024)        # the parse's memory, freed when parse_decls returns
    found: Array[weakref Decl] = []
    for word in src.split_whitespace():
        d = Decl(name=String(word)) using ast
        found.push(weakref d)                   # the link keeps `d`'s block in `ast`
    return found

fn main():
    decls = parse_decls("let x let y")
    for link in decls:
        if link exists as d:
            println(d.name)
        else:
            println("gone")

class Session:
    user: String

struct Index:
    recent: Array[weakref Session] = []

fn handle(ref mut index: Index, user: StrView):
    req = Arena.with_capacity(16 * 1024)        # this request's memory
    s = Session(user=String(user)) using req
    index.recent.push(weakref s)               # `index` lives on after `req` ends
    println(s.user)

fn main():
    index = Index()
    handle(ref mut index, "ana")
    for link in index.recent:
        if link exists as s:
            println(s.user)
        else:
            println("gone")

