    pool: thread_shared Pool
    fn drop():
        with this.pool.lock:
            this.pool.names.push(owns copy of this.name)

class Batch:
    conns: Array[thread_shared Conn] = []

fn main():
    pool = thread_shared Pool()
    b = Batch(conns=[thread_shared Conn(name=String("db-1"), pool=thread_shared pool)])
    h = thread.spawn(owns fn() owns b: b.conns.len())
    for frame in 0..1000:
        with pool.lock:
            for n in pool.names:
                println(n.to_upper())
    println(h.join())

import std.jobs
import std.hot
import std.mem
from std.sync import Lock

class World:
    lock: Lock = Lock()
    seen: Array[int] guarded by lock = [0]

class Item:
    id: int
    world: thread_shared World
    fn drop():
        println("item", this.id, "gone")

class Crate:
    items: Array[thread_shared Item] = []

fn run(world: thread_shared World, owns crate: Crate):
    pending: Option[Crate] = Some(crate)
    frame = 0
    while true:
        with world.lock:
            for id in world.seen:
                println(id)
        if frame == 600:
            if mem.take(ref mut pending) exists as c:
                jobs.submit(owns fn() owns c: c.items.len())
        hot.checkpoint()
        frame += 1

fn main():
    world = thread_shared World()
    run(world, owns Crate(items=[thread_shared Item(id=1, world=thread_shared world)]))

import std.jobs

class Texture:
    id: int
    fn drop():
        id = this.id
        jobs.submit(owns fn() copy of id: println("release", id))

class Bundle:
    textures: Array[thread_shared Texture] = []

fn load_all(ids: Span[int]) -> Array[Bundle]:
    out: Array[Bundle] = []
    with s = jobs.scope():
        for id in ids:
            s.submit(owns fn() copy of id: out.push(owns Bundle(textures=[thread_shared Texture(id=id)])))
    return out

fn main():
    bundles = load_all([1, 2])
    bundles.clear()
    for frame in 0..100000:
        if frame % 10000 == 0:
            println("frame", frame)

import std.thread
from std.sync import Lock

class Pool:
    lock: Lock = Lock()
    free: Array[int] guarded by lock = []

class Lease:
    id: int
    pool: thread_shared Pool
    fn drop():
        with this.pool.lock:
            this.pool.free.push(owns copy of this.id)

class Conn:
    lease: owns Lease

class Batch:
    conns: Array[thread_shared Conn] = []

fn main():
    pool = thread_shared Pool()
    b = Batch(conns=[thread_shared Conn(lease=owns Lease(id=1, pool=thread_shared pool))])
    h = thread.spawn(owns fn() owns b: b.conns.len())
    for frame in 0..1000:
        with pool.lock:
            for id in pool.free:
                println(id)
    println(h.join())

import std.jobs

class Texture:                            # a GPU texture a worker loaded
    id: int
    fn drop():
        println("texture", this.id, "freed")

class Bundle:                             # a plain object, combined into main's list
    textures: Array[thread_shared Texture] = []

fn load_all(ids: Span[int]) -> Array[Bundle]:
    out: Array[Bundle] = []
    with s = jobs.scope():
        for id in ids:
            s.submit(owns fn() copy of id: out.push(owns Bundle(textures=[thread_shared Texture(id=id)])))
    return out

fn render_frame(n: int):
    println("frame", n)

fn main():
    bundles = load_all([1, 2])
    bundles.clear()                       # each Texture goes back to the worker that made it
    for frame in 0..600:
        render_frame(frame)

import std.thread
from std.sync import Sender, channel

class Frame:
    id: int
    fn drop():
        println("frame", this.id, "recycled")

class Packet:
    frames: Array[thread_shared Frame] = []

unsafe extern "C":
    safe fn usleep(us: u32) -> i32

fn capture(tx: Sender[Packet]):
    tx.send(owns Packet(frames=[thread_shared Frame(id=1)])).expect("main is gone")
    r = usleep(2000000)
    println("slept", r)

fn main():
    tx, rx = channel[Packet](capacity=4)
    h = thread.spawn(owns fn() owns tx: capture(tx))
    if rx.recv() exists as p:
        println(p.frames.len())
    h.join()

import std.thread
from std.sync import Atomic, Lock

class World:
    live: Atomic[int] = Atomic(0)
    lock: Lock = Lock()
    names: Array[String] guarded by lock = []

class Body:
    world: thread_shared World
    fn drop():
        this.world.live.fetch_sub(1)

class Island:
    bodies: Array[thread_shared Body] = []

fn main():
    world = thread_shared World()
    world.live.fetch_add(1)
    isl = Island(bodies=[thread_shared Body(world=thread_shared world)])
    h = thread.spawn(owns fn() owns isl: isl.bodies.len())
    for step in 0..100:
        with world.lock:
            for n in world.names:
                println(n)
        println(world.live.load())
    println(h.join())
